def get_d2_pairs(G):
    n = G.number_of_nodes()
    count = 0
    for u, v in itertools.combinations(range(n), 2):
        if not G.has_edge(u, v):
            # Check if they have a common neighbor
            if any(G.has_edge(u, w) and G.has_edge(v, w) for w in range(n)):
                count += 1
    return count

def test_n(n):
    max_d2 = 0
    # Try all possible edge sets for small n
    edges = list(itertools.combinations(range(n), 2))
    for i in range(1 << len(edges)):
        G = nx.Graph()
        G.add_nodes_from(range(n))
        for j in range(len(edges)):
            if (i >> j) & 1:
                G.add_edge(*edges[j])
        max_d2 = max(max_d2, get_d2_pairs(G))
    return max_d2

for n in range(2, 6):
    print(f"n={n}, max_d2={test_n(n)}")
